633	fn rewrite_statements(
634	    statements: Vec<Statement>,
635	    component: &Component,
636	    bound: &HashSet<String>,
637	) -> Vec<Statement> {
638	    statements
639	        .into_iter()
640	        .map(|statement| rewrite_statement(statement, component, bound))
641	        .collect()
642	}
