644	fn rewrite_statement(
645	    statement: Statement,
646	    component: &Component,
647	    bound: &HashSet<String>,
648	) -> Statement {
649	    match statement {
650	        Statement::Assign {
651	            target,
652	            value,
653	            span,
654	        } => Statement::Assign {
655	            target: rewrite_lvalue(target, component, bound),
656	            value: rewrite_expr(value, component, bound),
657	            span,
658	        },
659	        Statement::If {
660	            condition,
661	            then_statements,
662	            else_statements,
663	            span,
664	        } => Statement::If {
665	            condition: rewrite_expr(condition, component, bound),
666	            then_statements: rewrite_statements(then_statements, component, bound),
667	            else_statements: rewrite_statements(else_statements, component, bound),
668	            span,
669	        },
670	        Statement::ForAll {
671	            binder,
672	            statements,
673	            span,
674	        } => {
675	            let binder = rewrite_binder(binder, component, bound);
676	            let mut nested = bound.clone();
677	            nested.insert(binder_name(&binder).to_owned());
678	            Statement::ForAll {
679	                binder,
680	                statements: rewrite_statements(statements, component, &nested),
681	                span,
682	            }
683	        }
684	    }
685	}
