708	#[allow(clippy::too_many_lines)]
709	fn rewrite_expr(expr: Expr, component: &Component, bound: &HashSet<String>) -> Expr {
710	    match expr {
711	        Expr::Var(name)
712	            if !bound.contains(&name)
713	                && (component.names.state.contains(&name)
714	                    || component.names.consts.contains(&name)) =>
715	        {
716	            Expr::Var(prefix(&component.alias, &name))
717	        }
718	        Expr::Some(expr) => Expr::Some(Box::new(rewrite_expr(*expr, component, bound))),
719	        Expr::Set(items) => Expr::Set(
720	            items
721	                .into_iter()
722	                .map(|item| rewrite_expr(item, component, bound))
723	                .collect(),
724	        ),
725	        Expr::Seq(items) => Expr::Seq(
726	            items
727	                .into_iter()
728	                .map(|item| rewrite_expr(item, component, bound))
729	                .collect(),
730	        ),
731	        Expr::Struct { name, fields } => Expr::Struct {
732	            name: if component.names.types.contains(&name) {
733	                prefix(&component.alias, &name)
734	            } else {
735	                name
736	            },
737	            fields: fields
738	                .into_iter()
739	                .map(|(name, expr)| (name, rewrite_expr(expr, component, bound)))
740	                .collect(),
741	        },
742	        Expr::Call { name, args, span } => Expr::Call {
743	            name,
744	            args: args
745	                .into_iter()
746	                .map(|arg| rewrite_expr(arg, component, bound))
747	                .collect(),
748	            span,
749	        },
750	        Expr::Index(base, index) => Expr::Index(
751	            Box::new(rewrite_expr(*base, component, bound)),
752	            Box::new(rewrite_expr(*index, component, bound)),
753	        ),
754	        Expr::Field(base, name) => {
755	            Expr::Field(Box::new(rewrite_expr(*base, component, bound)), name)
756	        }
757	        Expr::Method {
758	            receiver,
759	            name,
760	            args,
761	        } => Expr::Method {
762	            receiver: Box::new(rewrite_expr(*receiver, component, bound)),
763	            name,
764	            args: args
765	                .into_iter()
766	                .map(|arg| rewrite_expr(arg, component, bound))
767	                .collect(),
768	        },
769	        Expr::Binary { op, left, right } => Expr::Binary {
770	            op,
771	            left: Box::new(rewrite_expr(*left, component, bound)),
772	            right: Box::new(rewrite_expr(*right, component, bound)),
773	        },
774	        Expr::Neg(expr) => Expr::Neg(Box::new(rewrite_expr(*expr, component, bound))),
775	        Expr::Not(expr) => Expr::Not(Box::new(rewrite_expr(*expr, component, bound))),
776	        Expr::Conditional {
777	            condition,
778	            then_expr,
779	            else_expr,
780	            spans,
781	        } => Expr::Conditional {
782	            spans,
783	            condition: Box::new(rewrite_expr(*condition, component, bound)),
784	            then_expr: Box::new(rewrite_expr(*then_expr, component, bound)),
785	            else_expr: Box::new(rewrite_expr(*else_expr, component, bound)),
786	        },
787	        Expr::Is { expr, pattern } => Expr::Is {
788	            expr: Box::new(rewrite_expr(*expr, component, bound)),
789	            pattern,
790	        },
791	        Expr::Quantified {
792	            quantifier,
793	            binder,
794	            body,
795	        } => {
796	            let binder = rewrite_binder(binder, component, bound);
797	            let mut nested = bound.clone();
798	            nested.insert(binder_name(&binder).to_owned());
799	            Expr::Quantified {
800	                quantifier,
801	                binder,
802	                body: Box::new(rewrite_expr(*body, component, &nested)),
803	            }
804	        }
805	        Expr::Aggregate {
806	            kind,
807	            binder,
808	            value,
809	        } => {
810	            let binder = rewrite_binder(binder, component, bound);
811	            let mut nested = bound.clone();
812	            nested.insert(binder_name(&binder).to_owned());
813	            Expr::Aggregate {
814	                kind,
815	                binder,
816	                value: value.map(|expr| Box::new(rewrite_expr(*expr, component, &nested))),
817	            }
818	        }
819	        Expr::UnaryNamed { name, expr, span } => Expr::UnaryNamed {
820	            name,
821	            expr: Box::new(rewrite_expr(*expr, component, bound)),
822	            span,
823	        },
824	        Expr::BinaryNamed { name, left, right } => Expr::BinaryNamed {
825	            name,
826	            left: Box::new(rewrite_expr(*left, component, bound)),
827	            right: Box::new(rewrite_expr(*right, component, bound)),
828	        },
829	        Expr::TernaryNamed {
830	            name,
831	            first,
832	            second,
833	            third,
834	        } => Expr::TernaryNamed {
835	            name,
836	            first: Box::new(rewrite_expr(*first, component, bound)),
837	            second: Box::new(rewrite_expr(*second, component, bound)),
838	            third: Box::new(rewrite_expr(*third, component, bound)),
839	        },
840	        other => other,
